CREATE TABLE IF NOT EXISTS "__EFMigrationsHistory" (
    "MigrationId" character varying(150) NOT NULL,
    "ProductVersion" character varying(32) NOT NULL,
    CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY ("MigrationId")
);

START TRANSACTION;
CREATE TABLE "ErrorLogs" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Fecha" timestamp with time zone NOT NULL,
    "Mensaje" text,
    "StackTrace" text,
    "InnerException" text,
    "Endpoint" text,
    "Metodo" text,
    "Usuario" text,
    "Ip" text,
    CONSTRAINT "PK_ErrorLogs" PRIMARY KEY ("Id")
);

CREATE TABLE "EstadoPresupuesto" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Descripcion" text NOT NULL,
    CONSTRAINT "PK_EstadoPresupuesto" PRIMARY KEY ("Id")
);

CREATE TABLE "EstadosTrabajo" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Nombre" text NOT NULL,
    "Color" text NOT NULL,
    CONSTRAINT "PK_EstadosTrabajo" PRIMARY KEY ("Id")
);

CREATE TABLE "Perfiles" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Nombre" text NOT NULL,
    CONSTRAINT "PK_Perfiles" PRIMARY KEY ("Id")
);

CREATE TABLE "Provincias" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Nombre" text NOT NULL,
    CONSTRAINT "PK_Provincias" PRIMARY KEY ("Id")
);

CREATE TABLE "Sectores" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Nombre" text NOT NULL,
    "PerfilId" integer NOT NULL,
    CONSTRAINT "PK_Sectores" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Sectores_Perfiles_PerfilId" FOREIGN KEY ("PerfilId") REFERENCES "Perfiles" ("Id") ON DELETE RESTRICT
);

CREATE TABLE "Ciudades" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Nombre" text NOT NULL,
    "ProvinciaId" integer NOT NULL,
    CONSTRAINT "PK_Ciudades" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Ciudades_Provincias_ProvinciaId" FOREIGN KEY ("ProvinciaId") REFERENCES "Provincias" ("Id") ON DELETE CASCADE
);

CREATE TABLE "Tareas" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Descripcion" text NOT NULL,
    "SectorId" integer NOT NULL,
    CONSTRAINT "PK_Tareas" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Tareas_Sectores_SectorId" FOREIGN KEY ("SectorId") REFERENCES "Sectores" ("Id") ON DELETE CASCADE
);

CREATE TABLE "Clientes" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "NroCliente" text NOT NULL,
    "Nombre" text NOT NULL,
    "RazonSocial" text,
    "Direccion" text,
    "AddressShipToCode" text,
    "ProvinciaId" integer NOT NULL,
    "CiudadId" integer NOT NULL,
    "Email" text,
    "Activo" boolean NOT NULL,
    CONSTRAINT "PK_Clientes" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Clientes_Ciudades_CiudadId" FOREIGN KEY ("CiudadId") REFERENCES "Ciudades" ("Id"),
    CONSTRAINT "FK_Clientes_Provincias_ProvinciaId" FOREIGN KEY ("ProvinciaId") REFERENCES "Provincias" ("Id")
);

CREATE TABLE "Usuarios" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "UserName" text NOT NULL,
    "PasswordHash" text NOT NULL,
    "NombreApellido" text NOT NULL,
    "Email" text,
    "NumeroCelular" text,
    "Activo" boolean NOT NULL,
    "PerfilId" integer NOT NULL,
    "ProvinciaId" integer,
    "CiudadId" integer,
    "ClienteId" integer,
    CONSTRAINT "PK_Usuarios" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Usuarios_Ciudades_CiudadId" FOREIGN KEY ("CiudadId") REFERENCES "Ciudades" ("Id"),
    CONSTRAINT "FK_Usuarios_Clientes_ClienteId" FOREIGN KEY ("ClienteId") REFERENCES "Clientes" ("Id"),
    CONSTRAINT "FK_Usuarios_Perfiles_PerfilId" FOREIGN KEY ("PerfilId") REFERENCES "Perfiles" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_Usuarios_Provincias_ProvinciaId" FOREIGN KEY ("ProvinciaId") REFERENCES "Provincias" ("Id")
);

CREATE TABLE "Trabajos" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "FechaSolicitud" timestamp with time zone NOT NULL,
    "FechaInicio" timestamp with time zone,
    "FechaFinalizado" timestamp with time zone,
    "ClienteId" integer NOT NULL,
    "TecnicosAsignados" text,
    "TecnicoId" integer,
    "UsuarioCreacionId" integer NOT NULL,
    "EstadoId" integer NOT NULL,
    "SectorId" integer NOT NULL,
    "TareaId" integer NOT NULL,
    "Comentarios" text,
    "TrabajoRealizado" text,
    "Materiales" text,
    "FechaPagado" timestamp with time zone,
    CONSTRAINT "PK_Trabajos" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Trabajos_Clientes_ClienteId" FOREIGN KEY ("ClienteId") REFERENCES "Clientes" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_Trabajos_EstadosTrabajo_EstadoId" FOREIGN KEY ("EstadoId") REFERENCES "EstadosTrabajo" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_Trabajos_Sectores_SectorId" FOREIGN KEY ("SectorId") REFERENCES "Sectores" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_Trabajos_Tareas_TareaId" FOREIGN KEY ("TareaId") REFERENCES "Tareas" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_Trabajos_Usuarios_TecnicoId" FOREIGN KEY ("TecnicoId") REFERENCES "Usuarios" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_Trabajos_Usuarios_UsuarioCreacionId" FOREIGN KEY ("UsuarioCreacionId") REFERENCES "Usuarios" ("Id") ON DELETE RESTRICT
);

CREATE TABLE "Imagenes" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "TrabajoId" integer NOT NULL,
    "Tipo" text NOT NULL,
    "NombreArchivo" text NOT NULL,
    "RutaArchivo" text NOT NULL,
    "Extension" text,
    "Tamanio" bigint NOT NULL,
    "FechaCarga" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_Imagenes" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Imagenes_Trabajos_TrabajoId" FOREIGN KEY ("TrabajoId") REFERENCES "Trabajos" ("Id") ON DELETE CASCADE
);

CREATE TABLE "Presupuestos" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "FechaCarga" timestamp with time zone NOT NULL,
    "TecnicoId" integer NOT NULL,
    "UsuarioDecisionId" integer,
    "FechaDecision" timestamp with time zone,
    "EstadoId" integer NOT NULL,
    "MotivoRechazo" text,
    "Descripcion" text,
    "RutaArchivo" text,
    "TrabajoId" integer NOT NULL,
    CONSTRAINT "PK_Presupuestos" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Presupuestos_EstadoPresupuesto_EstadoId" FOREIGN KEY ("EstadoId") REFERENCES "EstadoPresupuesto" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_Presupuestos_Trabajos_TrabajoId" FOREIGN KEY ("TrabajoId") REFERENCES "Trabajos" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_Presupuestos_Usuarios_TecnicoId" FOREIGN KEY ("TecnicoId") REFERENCES "Usuarios" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_Presupuestos_Usuarios_UsuarioDecisionId" FOREIGN KEY ("UsuarioDecisionId") REFERENCES "Usuarios" ("Id")
);

CREATE TABLE "TrabajoFacturas" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "TrabajoId" integer NOT NULL,
    "RutaArchivo" text NOT NULL,
    "FechaCarga" timestamp with time zone NOT NULL,
    "FechaPagado" timestamp with time zone,
    CONSTRAINT "PK_TrabajoFacturas" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_TrabajoFacturas_Trabajos_TrabajoId" FOREIGN KEY ("TrabajoId") REFERENCES "Trabajos" ("Id") ON DELETE CASCADE
);

CREATE TABLE "TrabajoImagenComparaciones" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "TrabajoId" integer NOT NULL,
    "ImagenAntesId" integer,
    "ImagenDespuesId" integer,
    CONSTRAINT "PK_TrabajoImagenComparaciones" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_TrabajoImagenComparaciones_Imagenes_ImagenAntesId" FOREIGN KEY ("ImagenAntesId") REFERENCES "Imagenes" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_TrabajoImagenComparaciones_Imagenes_ImagenDespuesId" FOREIGN KEY ("ImagenDespuesId") REFERENCES "Imagenes" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_TrabajoImagenComparaciones_Trabajos_TrabajoId" FOREIGN KEY ("TrabajoId") REFERENCES "Trabajos" ("Id") ON DELETE CASCADE
);

