    CONSTRAINT "FK_Incidencias_Usuarios_UsuarioFinalizadoId" FOREIGN KEY ("UsuarioFinalizadoId") REFERENCES "Usuarios" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_Incidencias_Usuarios_UsuarioId" FOREIGN KEY ("UsuarioId") REFERENCES "Usuarios" ("Id") ON DELETE RESTRICT
);

